import type { LayerType } from '@chiwt/schema';
import { Bell, Captions, Filter, Image, Layers, MessageSquare, QrCode, Radio, Trash2, Type, Upload } from 'lucide-react';
import { useEffect, useRef, useState } from 'react';
import { useStudio } from '@/lib/store';

const OPTIONS: { type: LayerType; label: string; icon: typeof Radio }[] = [
  { type: 'live-badge', label: 'En vivo', icon: Radio },
  { type: 'chat', label: 'Chat', icon: MessageSquare },
  { type: 'alert', label: 'Alerta', icon: Bell },
  { type: 'lower-third', label: 'Zócalo', icon: Type },
  { type: 'watermark', label: 'Logo', icon: Image },
  { type: 'qr', label: 'QR', icon: QrCode },
  { type: 'lut', label: 'LUT', icon: Filter },
  { type: 'subtitle', label: 'Subtítulos', icon: Captions },
];

export function Sidebar() {
  const studio = useStudio();
  const project = studio.project!;
  const fileRef = useRef<HTMLInputElement>(null);
  const mediaRef = useRef<HTMLInputElement>(null);
  const assets = Object.entries(project.assets);

  return (
    <aside className="w-72 shrink-0 border-r border-border bg-[#0a0a0b] flex flex-col">
      <div className="h-14 px-4 flex items-center gap-2 border-b border-border">
        <Layers size={18} className="text-primary" />
        <div className="min-w-0">
          <div className="font-bold leading-none">Chiwt</div>
          <div className="text-[11px] text-white/40 truncate">{project.name}</div>
        </div>
      </div>
      <div className="p-3 border-b border-border space-y-2">
        <select aria-label="Proyecto" value={project.id} onChange={(event) => void studio.openProject(event.target.value)} className="w-full bg-black border border-white/10 rounded px-2 py-1.5 text-xs">
          {studio.projects.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}
        </select>
        <div className="flex gap-2">
          <button type="button" onClick={() => void studio.createProject()} className="flex-1 text-[11px] py-1.5 rounded bg-white/5">Nuevo</button>
          <button type="button" onClick={() => fileRef.current?.click()} className="flex-1 text-[11px] py-1.5 rounded bg-white/5 inline-flex items-center justify-center gap-1"><Upload size={12} /> Video</button>
          <button type="button" onClick={() => void studio.deleteProject()} className="text-[11px] px-2 rounded bg-white/5 text-white/50"><Trash2 size={12} /></button>
        </div>
        <button type="button" onClick={() => void studio.applyLivestream({ lut: 'cyberpunk', ratePerMinute: 16, instruction: 'público reaccionando a la escena como si fuera un livestream' })} className="w-full text-[11px] py-2 rounded bg-primary/15 text-primary font-semibold">
          Vestir como livestream
        </button>
        {project.video && (
          <label className="block space-y-1">
            <span className="text-[10px] uppercase tracking-wider text-white/35">Video de la línea</span>
            <NameField label="Nombre del video" value={project.video.fileName} onCommit={(name) => void studio.renameVideo(name)} />
          </label>
        )}
        <input ref={fileRef} type="file" accept="video/*" className="hidden" onChange={(event) => {
          const file = event.target.files?.[0];
          if (file) void studio.uploadVideo(file);
          event.target.value = '';
        }} />
      </div>
      <div className="p-3 grid grid-cols-4 gap-1.5 border-b border-border">
        {OPTIONS.map((option) => (
          <button key={option.type} type="button" onClick={() => void studio.addLayer(option.type)} className="flex flex-col items-center gap-1 py-2 rounded bg-white/5 text-[9px] text-white/75">
            <option.icon size={14} />
            {option.label}
          </button>
        ))}
      </div>
      <div className="border-b border-border">
        <div className="px-3 pt-3 pb-1 flex items-center justify-between">
          <span className="text-[10px] uppercase tracking-wider text-white/35">Incorporados</span>
          <button type="button" onClick={() => mediaRef.current?.click()} className="text-[11px] text-primary">Incorporar</button>
        </div>
        <div className="px-2 pb-2 max-h-40 overflow-y-auto space-y-1">
          {assets.length === 0 && <div className="text-[11px] text-white/30 px-2 py-2">Video, imagen o audio de este proyecto.</div>}
          {assets.map(([id, asset]) => (
            <div key={id} className="flex items-center gap-1 px-2 py-1.5 rounded bg-white/5">
              <span className="text-[9px] uppercase tracking-wide text-white/35 w-10 shrink-0">{asset.kind === 'image' ? 'img' : asset.kind === 'audio' ? 'audio' : 'video'}</span>
              {asset.kind === 'video'
                ? <NameField label={`Nombre de ${asset.name}`} value={asset.name} onCommit={(name) => void studio.renameAsset(id, name)} />
                : <span className="text-[11px] truncate flex-1" title={asset.name}>{asset.name}</span>}
              {asset.kind === 'image' && <button type="button" className="text-[10px] text-primary shrink-0" onClick={() => void studio.linkLogo({ assetId: id })}>Logo</button>}
              {asset.kind === 'video' && <button type="button" className="text-[10px] text-primary shrink-0" onClick={() => void studio.useAssetAsVideo(id)}>Línea</button>}
              <button type="button" className="text-[10px] text-white/40 shrink-0" onClick={() => void studio.removeAsset(id)} aria-label={`Quitar ${asset.name}`}>×</button>
            </div>
          ))}
        </div>
        <input ref={mediaRef} type="file" multiple accept="image/*,video/*,audio/*,.png,.jpg,.jpeg,.webp,.gif,.mp4,.webm,.mov,.mkv,.avi,.m4v,.mpg,.mpeg,.ts,.mts,.m2ts,.wmv,.flv,.mp3,.wav,.m4a,.aac,.ogg,.flac,.aiff,.aif,.opus" className="hidden" onChange={(event) => {
          const files = [...event.target.files ?? []];
          event.target.value = '';
          if (files.length) void studio.ingestFiles(files);
        }} />
      </div>
      <div className="px-3 py-2 text-[10px] uppercase tracking-wider text-white/35">Capas</div>
      <div className="flex-1 overflow-y-auto px-2 pb-3 space-y-1">
        {project.layers.length === 0 && <div className="text-xs text-white/30 px-2 py-4 text-center">Todavía no hay capas.</div>}
        {project.layers.map((layer) => {
          const option = OPTIONS.find((item) => item.type === layer.type);
          const Icon = option?.icon ?? Layers;
          const selected = studio.selectedLayerId === layer.id;
          return (
            <button key={layer.id} type="button" onClick={() => studio.setSelectedLayerId(layer.id)} className={`w-full flex items-center gap-2 px-2 py-2 rounded text-left text-sm ${selected ? 'bg-primary/15 text-primary' : 'text-white/75 hover:bg-white/5'}`}>
              <Icon size={14} />
              <span className="truncate flex-1">{layer.name}</span>
              {!layer.visible && <span className="text-[10px] text-white/30">oculta</span>}
            </button>
          );
        })}
      </div>
    </aside>
  );
}

function NameField({ label, value, onCommit }: { label: string; value: string; onCommit: (name: string) => void }) {
  const [draft, setDraft] = useState(value);
  const focused = useRef(false);
  useEffect(() => {
    if (!focused.current) setDraft(value);
  }, [value]);
  const commit = (raw: string) => {
    const next = raw.trim();
    if (!next || next === value) {
      setDraft(value);
      return;
    }
    setDraft(next);
    onCommit(next);
  };
  return (
    <input
      aria-label={label}
      value={draft}
      onFocus={() => { focused.current = true; }}
      onBlur={(event) => {
        focused.current = false;
        commit(event.currentTarget.value);
      }}
      onChange={(event) => setDraft(event.target.value)}
      onKeyDown={(event) => {
        if (event.key !== 'Enter') return;
        event.preventDefault();
        commit(event.currentTarget.value);
        event.currentTarget.blur();
      }}
      className="min-w-0 flex-1 bg-black border border-white/10 rounded px-2 py-1 text-[11px] outline-none focus:border-primary/50"
    />
  );
}

import { buildLutFilter, isLayerActiveAt } from '@chiwt/schema';
import { useState, useRef } from 'react';
import { Pause, Play, Square, Upload } from 'lucide-react';
import { LayerMenu, type LayerDraft } from '@/components/LayerMenu';
import { LayerView } from '@/components/LayerView';
import { formatClock } from '@/lib/format';
import { exportVideo } from '@/lib/exporter';
import { useStudio } from '@/lib/store';

export function VideoCanvas() {
  const studio = useStudio();
  const project = studio.project!;
  const frameRef = useRef<HTMLDivElement>(null);
  const videoRef = useRef<HTMLVideoElement>(null);
  const fileRef = useRef<HTMLInputElement>(null);
  const [aspect, setAspect] = useState(16 / 9);
  const [playing, setPlaying] = useState(false);
  const [exporting, setExporting] = useState(false);
  const [menu, setMenu] = useState<{ layerId: string; x: number; y: number; draft: LayerDraft } | null>(null);
  const [progress, setProgress] = useState(0);
  const cancelRef = useRef<{ cancel: () => void } | null>(null);
  const menuLayer = project.layers.find((layer) => layer.id === menu?.layerId);
  const activeLuts = project.layers.filter((layer) => layer.type === 'lut' && layer.lut && isLayerActiveAt(layer, studio.currentTime));
  const filter = activeLuts.length ? activeLuts.map((layer) => buildLutFilter(layer.lut!, layer.opacity / 100)).join(' ') : 'none';

  const seek = (time: number) => {
    if (videoRef.current) videoRef.current.currentTime = time;
    studio.setCurrentTime(time);
  };

  const toggle = () => {
    const video = videoRef.current;
    if (!video) return;
    if (video.paused) void video.play();
    else video.pause();
  };

  const startExport = () => {
    const video = videoRef.current;
    if (!video || exporting) return;
    try {
      const handle = exportVideo(video, project.layers, project.duration, studio.playbackRate, (assetId) => `/api/projects/${project.id}/assets/${assetId}`, setProgress);
      cancelRef.current = handle;
      setExporting(true);
      void handle.done.finally(() => {
        setExporting(false);
        cancelRef.current = null;
      });
    } catch (error) {
      studio.setCurrentTime(video.currentTime);
      alert(error instanceof Error ? error.message : 'No se pudo exportar.');
    }
  };

  return (
    <div className="flex-1 min-h-0 min-w-0 flex flex-col overflow-hidden">
      <div
        className="flex-1 min-h-0 min-w-0 bg-black p-4 overflow-hidden grid place-items-center"
        style={{ containerType: 'size' }}
      >
        <div
          ref={frameRef}
          className="relative bg-black mx-auto"
          style={{ aspectRatio: aspect, width: `min(100cqw, calc(100cqh * ${aspect}))`, height: `min(100cqh, calc(100cqw / ${aspect}))` }}
        >
          {project.video ? (
            <video
              key={project.videoToken}
              ref={videoRef}
              src={`/api/projects/${project.id}/video`}
              className="w-full h-full bg-black"
              style={{ filter }}
              playsInline
              onLoadedMetadata={(event) => {
                const video = event.currentTarget;
                if (video.videoWidth && video.videoHeight) setAspect(video.videoWidth / video.videoHeight);
              }}
              onTimeUpdate={(event) => studio.setCurrentTime(event.currentTarget.currentTime)}
              onPlay={() => setPlaying(true)}
              onPause={() => setPlaying(false)}
            />
          ) : (
            <button type="button" onClick={() => fileRef.current?.click()} className="w-[min(100%,960px)] aspect-video grid place-items-center text-white/50 border border-dashed border-white/15 rounded-lg">
              <span className="flex flex-col items-center gap-1 text-sm"><span className="flex items-center gap-2"><Upload size={16} /> Soltá el video en bruto</span><span className="text-[11px] text-white/35">El audio y el sonido también se sueltan sobre el proyecto</span></span>
            </button>
          )}
          {project.layers.map((layer) => (
            <LayerView
              key={layer.id}
              layer={layer}
              projectId={project.id}
              currentTime={studio.currentTime}
              selected={studio.selectedLayerId === layer.id}
              frameRef={frameRef}
              onSelect={() => studio.setSelectedLayerId(layer.id)}
              onMove={(position) => void studio.moveLayer(layer.id, position)}
              onResize={(box) => {
                setMenu((current) => current?.layerId === layer.id ? { ...current, draft: { ...current.draft, size: { width: box.width, height: box.height } } } : current);
                void studio.commitLayer(layer.id, { position: { x: box.x, y: box.y }, size: { width: box.width, height: box.height } });
              }}
              preview={menu?.layerId === layer.id ? menu.draft : null}
              onOpenMenu={(point) => setMenu({ layerId: layer.id, ...point, draft: { size: { ...layer.size }, rotate: layer.transform.rotate } })}
            />
          ))}
        </div>
        {menuLayer && menu && (
          <LayerMenu
            layer={menuLayer}
            point={menu}
            draft={menu.draft}
            onDraft={(draft) => setMenu((current) => current ? { ...current, draft } : current)}
            onCommit={(draft) => {
              const sameSize = draft.size.width === menuLayer.size.width && draft.size.height === menuLayer.size.height;
              const sameRotate = draft.rotate === menuLayer.transform.rotate;
              if (sameSize && sameRotate) return;
              void studio.commitLayer(menuLayer.id, {
                size: draft.size,
                transform: { scale: menuLayer.transform.scale, rotate: draft.rotate },
              });
            }}
            onClose={() => setMenu(null)}
          />
        )}
      </div>
      <div className="h-14 shrink-0 border-t border-border px-4 flex items-center gap-3 bg-[#0a0a0b]">
        <button type="button" onClick={toggle} disabled={!project.video || exporting} className="w-8 h-8 grid place-items-center rounded-md bg-white/5 disabled:opacity-30">
          {playing ? <Pause size={14} /> : <Play size={14} />}
        </button>
        <input
          aria-label="Tiempo"
          type="range"
          min={0}
          max={project.duration || 0}
          step={0.01}
          value={Math.min(studio.currentTime, project.duration || 0)}
          disabled={!project.video}
          onChange={(event) => seek(Number(event.target.value))}
          className="flex-1 accent-cyan-400"
        />
        <span className="text-xs tabular-nums text-white/60 w-24 text-right">{formatClock(studio.currentTime)} / {formatClock(project.duration)}</span>
        <select aria-label="Velocidad" value={studio.playbackRate} onChange={(event) => {
          const rate = Number(event.target.value);
          studio.setPlaybackRate(rate);
          if (videoRef.current) videoRef.current.playbackRate = rate;
        }} className="bg-black border border-white/10 rounded px-2 py-1 text-xs">
          {[0.5, 1, 1.5, 2].map((rate) => <option key={rate} value={rate}>{rate}×</option>)}
        </select>
        {exporting ? (
          <button type="button" onClick={() => cancelRef.current?.cancel()} className="text-xs px-3 py-1.5 rounded bg-red-500/20 text-red-200 flex items-center gap-1">
            <Square size={12} /> {Math.round(progress)}%
          </button>
        ) : (
          <button type="button" onClick={startExport} disabled={!project.video} className="text-xs px-3 py-1.5 rounded bg-primary/20 text-primary disabled:opacity-30">Exportar</button>
        )}
        <input ref={fileRef} type="file" accept="video/mp4,video/webm,video/quicktime,video/x-matroska,video/x-msvideo,.mkv,.avi" className="hidden" onChange={(event) => {
          const file = event.target.files?.[0];
          if (file) void studio.uploadVideo(file);
          event.target.value = '';
        }} />
      </div>
      {(studio.notice || studio.error || studio.busy) && (
        <div className={`px-4 py-1.5 text-xs border-t border-border ${studio.error ? 'text-red-300' : 'text-white/60'}`}>
          {studio.busy ?? studio.error ?? studio.notice}
        </div>
      )}
    </div>
  );
}

@import 'tailwindcss';

@theme inline {
  --color-background: hsl(var(--background));
  --color-foreground: hsl(var(--foreground));
  --color-border: hsl(var(--border));
  --color-primary: hsl(var(--primary));
  --color-primary-foreground: hsl(var(--primary-foreground));
  --color-muted: hsl(var(--muted));
  --color-muted-foreground: hsl(var(--muted-foreground));
  --font-sans: 'Inter', ui-sans-serif, system-ui, sans-serif;
}

:root {
  --background: 240 5% 4%;
  --foreground: 0 0% 98%;
  --border: 240 5% 15%;
  --primary: 195 100% 50%;
  --primary-foreground: 0 0% 0%;
  --muted: 240 5% 12%;
  --muted-foreground: 240 5% 65%;
}

@layer base {
  * { @apply border-border; }
  body { @apply font-sans antialiased bg-background text-foreground; }
  button, input, textarea, select { font: inherit; }
}

@keyframes layer-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.04); }
}
@keyframes layer-blink {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.25; }
}
@keyframes layer-fade-in {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes layer-slide-in {
  from { transform: translateY(16px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
}

.anim-pulse { animation: layer-pulse 2s infinite ease-in-out; }
.anim-blink { animation: layer-blink 1s infinite; }
.anim-fade-in { animation: layer-fade-in 0.45s ease-out forwards; }
.anim-slide-in { animation: layer-slide-in 0.45s ease-out forwards; }

import type {
  AlertInput,
  LayerPatch,
  LayerType,
  LutData,
  ManualMessageInput,
  Project,
  SectorInput,
  SectorPatch,
} from '@chiwt/schema';

export class ApiError extends Error {
  status: number;
  constructor(message: string, status: number) {
    super(message);
    this.status = status;
  }
}

type ProjectResponse = { project: Project; message?: string; assetId?: string };

async function request<T>(url: string, init?: RequestInit): Promise<T> {
  const response = await fetch(url, init);
  const data = await response.json().catch(() => null);
  if (!response.ok) {
    const message = data && typeof data.error === 'string' ? data.error : `Error ${response.status}`;
    throw new ApiError(message, response.status);
  }
  return data as T;
}

function json(body: unknown): RequestInit {
  return { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify(body) };
}

const VIDEO_MIME: Record<string, string> = {
  mp4: 'video/mp4',
  webm: 'video/webm',
  mov: 'video/quicktime',
  mkv: 'video/x-matroska',
  avi: 'video/x-msvideo',
  m4v: 'video/mp4',
  mpg: 'video/mpeg',
  mpeg: 'video/mpeg',
  ts: 'video/mp2t',
  mts: 'video/mp2t',
  m2ts: 'video/mp2t',
  wmv: 'video/x-ms-wmv',
  flv: 'video/x-flv',
};

const FILE_MIME: Record<string, string> = {
  ...VIDEO_MIME,
  png: 'image/png',
  jpg: 'image/jpeg',
  jpeg: 'image/jpeg',
  webp: 'image/webp',
  gif: 'image/gif',
  mp3: 'audio/mpeg',
  wav: 'audio/wav',
  m4a: 'audio/mp4',
  aac: 'audio/aac',
  ogg: 'audio/ogg',
  flac: 'audio/flac',
  aiff: 'audio/aiff',
  aif: 'audio/aiff',
  opus: 'audio/opus',
};

const API_ORIGIN = (import.meta.env.VITE_CHWIT_API as string | undefined)?.replace(/\/$/, '') || 'http://127.0.0.1:8787';

export function mediaKind(file: File): 'video' | 'audio' | 'image' | null {
  if (file.type.startsWith('video/')) return 'video';
  if (file.type.startsWith('audio/')) return 'audio';
  if (file.type.startsWith('image/')) return 'image';
  const ext = file.name.split('.').pop()?.toLowerCase() ?? '';
  if (ext in VIDEO_MIME) return 'video';
  if (['mp3', 'wav', 'm4a', 'aac', 'ogg', 'flac', 'aiff', 'aif', 'opus'].includes(ext)) return 'audio';
  if (['png', 'jpg', 'jpeg', 'webp', 'gif'].includes(ext)) return 'image';
  return null;
}

function upload<T>(path: string, file: File, onProgress?: (percent: number) => void): Promise<T> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('POST', `${API_ORIGIN}${path}`);
    xhr.setRequestHeader('content-type', contentType(file));
    xhr.setRequestHeader('x-filename', encodeURIComponent(file.name));
    xhr.upload.onprogress = (event) => {
      if (!onProgress || !event.lengthComputable || event.total <= 0) return;
      onProgress(Math.min(100, Math.round((event.loaded / event.total) * 100)));
    };
    xhr.onload = () => {
      const data = parseJson(xhr.responseText);
      if (xhr.status < 200 || xhr.status >= 300) {
        const message = data && typeof data.error === 'string' ? data.error : `Error ${xhr.status}`;
        reject(new ApiError(message, xhr.status));
        return;
      }
      resolve(data as T);
    };
    xhr.onerror = () => reject(new ApiError('No se pudo subir el archivo.', 0));
    xhr.onabort = () => reject(new ApiError('Se canceló la subida.', 0));
    xhr.send(file);
  });
}

function parseJson(raw: string): { error?: string } | null {
  try {
    return JSON.parse(raw) as { error?: string };
  } catch {
    return null;
  }
}

function mimeFromName(name: string): string {
  const ext = name.split('.').pop()?.toLowerCase() ?? '';
  return FILE_MIME[ext] ?? 'application/octet-stream';
}

function contentType(file: File): string {
  if (file.type && file.type !== 'application/octet-stream') return file.type;
  return mimeFromName(file.name);
}

export const api = {
  health: () => request<{ status: string; nan: boolean }>('/api/healthz'),
  list: () => request<{ projects: { id: string; name: string; revision: number; updatedAt: string; duration: number; hasVideo: boolean }[] }>('/api/projects'),
  create: (name: string) => request<ProjectResponse>('/api/projects', json({ name })),
  get: (id: string) => request<ProjectResponse>(`/api/projects/${id}`),
  remove: (id: string) => request<{ ok: boolean }>(`/api/projects/${id}`, { method: 'DELETE' }),
  uploadVideo: (id: string, file: File, onProgress?: (percent: number) => void) => upload<ProjectResponse>(`/api/projects/${id}/video`, file, onProgress),
  uploadAsset: (id: string, file: File, onProgress?: (percent: number) => void) => upload<ProjectResponse>(`/api/projects/${id}/assets`, file, onProgress),
  renameVideo: (id: string, fileName: string) => request<ProjectResponse>(`/api/projects/${id}/video`, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ fileName }),
  }),
  renameAsset: (id: string, assetId: string, name: string) => request<ProjectResponse>(`/api/projects/${id}/assets/${assetId}`, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ name }),
  }),
  removeAsset: (id: string, assetId: string) => request<ProjectResponse>(`/api/projects/${id}/assets/${assetId}`, { method: 'DELETE' }),
  useAssetAsVideo: (id: string, assetId: string) => request<ProjectResponse>(`/api/projects/${id}/assets/${assetId}/use-as-video`, { method: 'POST' }),
  linkLogo: (id: string, body: { assetId?: string; start?: number; end?: number | null; spin?: boolean; rotate?: number }) => request<ProjectResponse>(`/api/projects/${id}/logo`, json(body)),
  addLayer: (id: string, type: LayerType) => request<ProjectResponse>(`/api/projects/${id}/layers`, json({ type })),
  patchLayer: (id: string, layerId: string, patch: LayerPatch) => request<ProjectResponse>(`/api/projects/${id}/layers/${layerId}`, {
    method: 'PATCH',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify(patch),
  }),
